const ridgeAt = (R, s, d, x, z) => { const [off, wl, wr] = ridgeS(R, s), u = d < off ? (off - d) / (off + wl) : (d - off) / (wr - off); return ridgeTop(R, ridgeH(R, s), u, x, z); };
