export const lipBare = (th) => Math.max(0, cropBack(th) - lipBite(th));
const CROP_BACK_MOST = 13.0;                                  // (cropBack's most: 11.05 as told over the whole lip at a hundred-thousandth of a radian (round three d; it was 10.69); its crests' sum, 13.58, is met nowhere on the lip: the terms are fixed waves of the angle)
const lipSod = (th) => 0.3 * sstep(0.2, 0.8, Math.sin(th * 90 / 0.83 + 1.9 * Math.sin(th * 90 / 2.9 + 1.1))) - 0.08;
