const SEAM_BASES = BEDS.map((b, i) => (i && b.out < -0.2 ? BEDS[i - 1].top : null)).filter((t) => t !== null);
// A PLACE'S HEIGHT IN THE BEDS' OWN FRAME: they dip gently to the east and the north and they roll a little. (Sines only: the
// shader's bedH is this same sum, and the two agree to a float's last figures; and the outline takes each corner's bed at
// the height where the corner comes to stand, cut back or sunk, not at the unbroken round's: so a bed's ledge in the mesh
// lies under that bed's colour. shots/the-digging-wheel/round2/pitmend/faces.mjs tells how many of the face corners in
// sight within 0.62 rad stand within 4 mm of the height their bed was taken at.)
// ROUND THREE B, BY THE LEAD'S RULING: THE FAULTS' THROW IS TAKEN OUT, everywhere. One of the planes crossed the middle
// face 12 m south of the wheel's plane (th 0.177) and threw the beds 0.46 m: a stranger read the bands' jump on a vertical
// line as two panels that do not line up. The beds now run unbroken (they dip and roll as before): the term
// 1.7 * sin(k * 2.4 + 0.7 * sin(k * 1.3 + 0.5)), k the block's number, is gone from this sum and from the shader's bedH alike.
