      col = mix(col, vec3(0.46, 0.40, 0.31), 0.5 * smoothstep(0.5, 0.7, fbm(vW * 0.9 + 9.)));      // (clay in it, dried grey)
      col *= (0.62 + 0.38 * smoothstep(0.0, 0.45, vW.y)) * (1. - 0.3 * smoothstep(0.55, 0.75, vnoise(vW * 5.3)) * (1. - smoothstep(0.03, 0.1, foot)));
